/**
 * ContactTrigger
 *
 * Slim, bulk-safe trigger: contains no SOQL, no DML and no business logic.
 * All processing is delegated to ContactTriggerHandler, which stays within a
 * budget of 2 SOQL queries and 1 DML statement for a batch of up to 200
 * contacts (before and after contexts combined).
 */
trigger ContactTrigger on Contact (before insert, before update, after insert) {
    if (Trigger.isBefore) {
        ContactTriggerHandler.handleBeforeInsertOrUpdate(Trigger.isInsert, Trigger.new);
    }
    if (Trigger.isAfter && Trigger.isInsert) {
        ContactTriggerHandler.handleAfterInsert(Trigger.new);
    }
}
