/**
 * ContactTriggerHandler
 *
 * Bulk-safe handler for the Contact trigger. The trigger contains no SOQL or
 * DML; all queries and DML are performed here, in bulk.
 *
 * Budget for an insert or update of up to 200 contacts:
 *   - Before context:        1 SOQL query (parent accounts for the
 *                            MailingCountry / LeadSource defaults).
 *   - After-insert context:  1 SOQL query + 1 bulk DML statement
 *                            (copy the contact phone onto the account).
 *   - Total:                 at most 2 SOQL queries and 1 DML statement.
 */
public class ContactTriggerHandler {

    /**
     * Before insert / before update.
     * Defaults MailingCountry from the parent account's BillingCountry and,
     * for inserts only, LeadSource from the parent account's AccountSource,
     * exactly as the original trigger did, using one bulk query.
     */
    public static void handleBeforeInsertOrUpdate(Boolean isInsert, List<Contact> newContacts) {
        Set<Id> accountIds = collectAccountIds(newContacts, false);
        if (accountIds.isEmpty()) {
            return;
        }

        Map<Id, Account> accountMap = new Map<Id, Account>(
            [SELECT BillingCountry, AccountSource FROM Account WHERE Id IN :accountIds]
        );

        for (Contact c : newContacts) {
            if (c.AccountId == null) {
                continue;
            }
            Account a = accountMap.get(c.AccountId);
            if (a == null) {
                // Preserve the original trigger behaviour: the per-record
                // single-row query throws when the account does not exist.
                throw new System.NoSuchRowException('No rows found');
            }
            if (String.isBlank(c.MailingCountry)) {
                c.MailingCountry = a.BillingCountry;
            }
            if (isInsert && String.isBlank(c.LeadSource)) {
                c.LeadSource = a.AccountSource;
            }
        }
    }

    /**
     * After insert.
     * For every parent account that has no phone, copies the phone of the
     * first new contact (in trigger order) that belongs to it and has a
     * phone. Updating the map entries in place means later contacts of the
     * same account see a non-blank phone and are skipped, so the first
     * contact in trigger order wins and each account is updated exactly
     * once, in a single bulk DML statement.
     */
    public static void handleAfterInsert(List<Contact> newContacts) {
        Set<Id> accountIds = collectAccountIds(newContacts, true);
        if (accountIds.isEmpty()) {
            return;
        }

        Map<Id, Account> accountMap = new Map<Id, Account>(
            [SELECT Id, Phone FROM Account WHERE Id IN :accountIds]
        );

        List<Account> accountsToUpdate = new List<Account>();
        for (Contact c : newContacts) {
            if (c.AccountId == null || String.isBlank(c.Phone)) {
                continue;
            }
            Account a = accountMap.get(c.AccountId);
            if (a == null) {
                // Preserve the original trigger behaviour: the per-record
                // single-row query throws when the account does not exist.
                throw new System.NoSuchRowException('No rows found');
            }
            if (String.isBlank(a.Phone)) {
                a.Phone = c.Phone;
                accountsToUpdate.add(a);
            }
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }

    /**
     * Collects the distinct parent account ids relevant to the current
     * operation. When requirePhone is true (after-insert phone copy), only
     * contacts that carry a phone are considered.
     */
    private static Set<Id> collectAccountIds(List<Contact> newContacts, Boolean requirePhone) {
        Set<Id> accountIds = new Set<Id>();
        for (Contact c : newContacts) {
            if (c.AccountId != null && (!requirePhone || String.isNotBlank(c.Phone))) {
                accountIds.add(c.AccountId);
            }
        }
        return accountIds;
    }
}
