```apex
/**
 * Nightly purge job for FB_Integration_Log__c integration logs.
 *
 * Retention policy:
 *  - Non-ERROR logs (including blank Level__c): deleted once older than 30 days.
 *  - ERROR logs: kept until older than 180 days, then deleted.
 *
 * The class is bulk-safe: IDs are collected with a single SOQL query and
 * deleted in chunks below the 10,000-record DML limit.
 */
global class LogPurgeJob implements Schedulable {

    /**
     * Max records deleted per DML statement (governor limit is 10,000).
     */
    private static final Integer DELETE_BATCH_SIZE = 5000;

    /**
     * Max records fetched per SOQL query (governor limit is 50,000).
     */
    private static final Integer QUERY_BATCH_SIZE = 50000;

    /**
     * Schedulable requires a no-argument constructor.
     */
    public LogPurgeJob() {
    }

    /**
     * Deletes integration logs that are past their retention period.
     */
    global void execute(SchedulableContext context) {
        // Non-ERROR logs (blank level included): older than 30 days.
        // ERROR logs: older than 180 days.
        // Note: SOQL != does not match null, so blanks are handled with
        // (Level__c != 'ERROR' OR Level__c = NULL).
        String query =
            'SELECT Id FROM FB_Integration_Log__c'
            + ' WHERE (CreatedDate < LAST_N_DAYS:30'
            + '        AND (Level__c != \'ERROR\' OR Level__c = NULL))'
            + '    OR (CreatedDate < LAST_N_DAYS:180)';

        // Process in query-sized pages; each page is fully deleted before the
        // next query, so the loop converges even with more than 50k rows.
        while (true) {
            List<Id> idsToDelete = new List<Id>();
            for (FB_Integration_Log__c log : [query]) {
                idsToDelete.add(log.Id);
            }

            if (idsToDelete.isEmpty()) {
                break;
            }

            for (Integer offset = 0; offset < idsToDelete.size(); offset += DELETE_BATCH_SIZE) {
                Integer end = Math.min(offset + DELETE_BATCH_SIZE, idsToDelete.size());
                delete idsToDelete.subList(offset, end);
            }
        }
    }

    /**
     * Schedules the purge to run every day at 02:00 (org timezone).
     *
     * @return the Id of the CronTrigger created by the scheduling call.
     */
    public static Id scheduleNightly() {
        String cronExpression = '0 0 2 ? * * *';
        return System.schedule('Log purge (nightly)', cronExpression, new LogPurgeJob());
    }
}
