/**
 * Pure unit tests for OpportunityForecastService.weightedAmountByStage.
 *
 * No DML and no SOQL: the OpportunitiesSelector is mocked with fflib-Apex-Mocks
 * and registered through Application.Selector.setMock, and the opportunities are
 * built in memory with fake ids from fflib_IDGenerator.
 */
@isTest
public class OpportunityForecastServiceTest {

    private static final String[] BULK_STAGE_NAMES = new String[] {
        'Identification', 'Qualification', 'Proposal', 'Negotiation'
    };
    private static final Integer BULK_OPPORTUNITIES_PER_STAGE = 63; // 4 x 63 = 252, above the 200-record batch boundary

    private static fflib_ApexMocks mocks;
    private static fflib_IDGenerator idGenerator;
    private static IOpportunitiesSelector mockSelector;

    // ------------------------------------------------------------------
    // Behaviour: per-stage weighted totals
    // ------------------------------------------------------------------

    @isTest
    static void shouldSumWeightedAmountsPerStage_WhenMultipleStagesReturned() {
        // Given
        prepareTestContext();
        Set<Id> accountIds = new Set<Id> { idGenerator.newId() };
        List<Opportunity> opportunities = new List<Opportunity> {
            buildOpportunity('Prospecting', 1000, 20),        // 1000 * 20 / 100       = 200.00
            buildOpportunity('Prospecting', 500, 40),         //  500 * 40 / 100       = 200.00
            buildOpportunity('Qualification', 333.33, 33.33), // 333.33 * 33.33 / 100 = 111.098889 -> 111.10
            buildOpportunity('Negotiation', 2500, 12.5)       // 2500 * 12.5 / 100    = 312.50
        };
        stubOpenOpportunities(opportunities);

        // When
        Test.startTest();
        Map<String, Decimal> result = OpportunityForecastService.weightedAmountByStage(accountIds);
        Test.stopTest();

        // Then
        Assert.areEqual(3, result.size(), 'Expected one total per stage');
        Assert.areEqual(400.00, result.get('Prospecting'), 'Prospecting should be 200.00 + 200.00');
        Assert.areEqual(111.10, result.get('Qualification'), 'Qualification should be 111.098889 rounded to 111.10');
        Assert.areEqual(312.50, result.get('Negotiation'), 'Negotiation should be 312.50');
        verifySelectorCalledOnce();
    }

    @isTest
    static void shouldRoundEachOpportunityToTwoDecimals_WhenWeightedAmountHasMoreDecimals() {
        // Given: each opportunity weighs 100 * 33.335 / 100 = 33.335, which rounds to 33.34
        prepareTestContext();
        Set<Id> accountIds = new Set<Id> { idGenerator.newId() };
        List<Opportunity> opportunities = new List<Opportunity> {
            buildOpportunity('Prospecting', 100, 33.335),
            buildOpportunity('Prospecting', 100, 33.335)
        };
        stubOpenOpportunities(opportunities);

        // When
        Test.startTest();
        Map<String, Decimal> result = OpportunityForecastService.weightedAmountByStage(accountIds);
        Test.stopTest();

        // Then: 33.34 + 33.34 = 66.68; rounding after summing would give 66.67
        Assert.areEqual(66.68, result.get('Prospecting'),
            'Each opportunity must be rounded to 2 decimals before the per-stage sum');
    }

    // ------------------------------------------------------------------
    // Behaviour: opportunities without Amount or Probability are ignored
    // ------------------------------------------------------------------

    @isTest
    static void shouldIgnoreOpportunities_WhenAmountIsNull() {
        // Given
        prepareTestContext();
        Set<Id> accountIds = new Set<Id> { idGenerator.newId() };
        List<Opportunity> opportunities = new List<Opportunity> {
            buildOpportunity('Qualification', null, 50),
            buildOpportunity('Prospecting', 1000, 10) // 1000 * 10 / 100 = 100.00
        };
        stubOpenOpportunities(opportunities);

        // When
        Test.startTest();
        Map<String, Decimal> result = OpportunityForecastService.weightedAmountByStage(accountIds);
        Test.stopTest();

        // Then
        Assert.areEqual(1, result.size(), 'Opportunities with a null Amount must not contribute');
        Assert.areEqual(100.00, result.get('Prospecting'), 'Only the opportunity with an Amount should contribute');
        Assert.isNull(result.get('Qualification'), 'A null-Amount opportunity must not create a stage total');
    }

    @isTest
    static void shouldIgnoreOpportunities_WhenProbabilityIsNull() {
        // Given
        prepareTestContext();
        Set<Id> accountIds = new Set<Id> { idGenerator.newId() };
        List<Opportunity> opportunities = new List<Opportunity> {
            buildOpportunity('Qualification', 1000, null),
            buildOpportunity('Prospecting', 2000, 25) // 2000 * 25 / 100 = 500.00
        };
        stubOpenOpportunities(opportunities);

        // When
        Test.startTest();
        Map<String, Decimal> result = OpportunityForecastService.weightedAmountByStage(accountIds);
        Test.stopTest();

        // Then
        Assert.areEqual(1, result.size(), 'Opportunities with a null Probability must not contribute');
        Assert.areEqual(500.00, result.get('Prospecting'), 'Only the opportunity with a Probability should contribute');
        Assert.isNull(result.get('Qualification'), 'A null-Probability opportunity must not create a stage total');
    }

    // ------------------------------------------------------------------
    // Behaviour: null/empty account ids short-circuit without calling the selector
    // ------------------------------------------------------------------

    @isTest
    static void shouldReturnEmptyMap_WhenAccountIdsIsNull() {
        // Given: a stubbed selector that holds data, to prove it is never consulted
        prepareTestContext();
        stubOpenOpportunities(new List<Opportunity> {
            buildOpportunity('Prospecting', 1000, 20)
        });

        // When
        Test.startTest();
        Map<String, Decimal> result = OpportunityForecastService.weightedAmountByStage(null);
        Test.stopTest();

        // Then
        Assert.areEqual(0, result.size(), 'Null account ids must produce an empty map');
        verifySelectorNotCalled();
    }

    @isTest
    static void shouldReturnEmptyMap_WhenAccountIdsIsEmpty() {
        // Given: a stubbed selector that holds data, to prove it is never consulted
        prepareTestContext();
        stubOpenOpportunities(new List<Opportunity> {
            buildOpportunity('Prospecting', 1000, 20)
        });

        // When
        Test.startTest();
        Map<String, Decimal> result = OpportunityForecastService.weightedAmountByStage(new Set<Id>());
        Test.stopTest();

        // Then
        Assert.areEqual(0, result.size(), 'An empty set of account ids must produce an empty map');
        verifySelectorNotCalled();
    }

    // ------------------------------------------------------------------
    // Behaviour: the selector returns no open opportunities
    // ------------------------------------------------------------------

    @isTest
    static void shouldReturnEmptyMap_WhenNoOpenOpportunities() {
        // Given
        prepareTestContext();
        Set<Id> accountIds = new Set<Id> { idGenerator.newId() };
        stubOpenOpportunities(new List<Opportunity>());

        // When
        Test.startTest();
        Map<String, Decimal> result = OpportunityForecastService.weightedAmountByStage(accountIds);
        Test.stopTest();

        // Then
        Assert.areEqual(0, result.size(), 'No open opportunities must produce an empty map');
        verifySelectorCalledOnce();
    }

    // ------------------------------------------------------------------
    // Bulk: 252 opportunities, above the 200-record batch boundary
    // ------------------------------------------------------------------

    @isTest
    static void shouldSumBulkOpportunities_When252OpportunitiesReturned() {
        // Given: 4 stages x 63 opportunities = 252, each worth 1000 * 20 / 100 = 200.00
        prepareTestContext();
        Set<Id> accountIds = new Set<Id> { idGenerator.newId(), idGenerator.newId(), idGenerator.newId() };
        List<Opportunity> opportunities = new List<Opportunity>();
        for (Integer i = 0; i < BULK_STAGE_NAMES.size() * BULK_OPPORTUNITIES_PER_STAGE; i++) {
            opportunities.add(buildOpportunity(BULK_STAGE_NAMES[i % BULK_STAGE_NAMES.size()], 1000, 20));
        }
        stubOpenOpportunities(opportunities);

        // When
        Test.startTest();
        Map<String, Decimal> result = OpportunityForecastService.weightedAmountByStage(accountIds);
        Test.stopTest();

        // Then: each stage total = 63 x 200.00 = 12600.00
        Decimal expectedPerStage = new Decimal(BULK_OPPORTUNITIES_PER_STAGE) * 1000 * 20 / 100;
        Assert.areEqual(BULK_STAGE_NAMES.size(), result.size(), 'Expected one total per stage');
        for (String stageName : BULK_STAGE_NAMES) {
            Assert.areEqual(expectedPerStage, result.get(stageName),
                'Expected ' + expectedPerStage + ' for stage ' + stageName);
        }
        verifySelectorCalledOnce();
    }

    // ------------------------------------------------------------------
    // Helpers
    // ------------------------------------------------------------------

    /**
     * Creates a fresh fflib_ApexMocks and fflib_IDGenerator for the test, mocks
     * IOpportunitiesSelector and clears any selector mock left behind by a
     * previous test method (static state persists across test methods within a
     * test class).
     */
    private static void prepareTestContext() {
