/**
 * A domain class for the Opportunity SObject.
 *
 * Validation rules:
 * 1. On insert and on update, Amount must not be negative.
 * 2. On update, an opportunity whose stage was already Closed Won before the
 *    update cannot have its Amount changed. (Closing an opportunity as won
 *    and changing its Amount in the same update is allowed.)
 *
 * Each error is raised on the Amount field of the offending record only, so
 * other records in the same DML statement are still saved. Errors are passed
 * through the domain's error(message, record, field) helper, which records
 * them in fflib_SObjectDomain.Errors for unit tests.
 */
public class Opportunities extends fflib_SObjectDomain {

    /**
     * The standard constructor for the Opportunities domain class.
     */
    public class Constructor implements fflib_SObjectDomain.IConstructable {

        public final Opportunity opportunity;

        public Constructor(Opportunity opportunity) {
            this.opportunity = opportunity;
        }

        public SObject getSObject() {
            return opportunity;
        }

        public Schema.SObjectType getSObjectType() {
            return Opportunity.SObjectType;
        }

        public fflib_SObjectDomain build() {
            return new Opportunities(this);
        }
    }

    /**
     * Constructs the domain class from a constructable.
     *
     * @param c the constructable used to construct the domain class
     */
    public Opportunities(fflib_SObjectDomain.IConstructable c) {
        super(c);
    }

    /**
     * Before insert: Amount must not be negative.
     */
    public override void validateBeforeInsert() {
        validateAmountNotNegative((Opportunity) getSObject());
    }

    /**
     * Before update: Amount must not be negative, and an opportunity that was
     * already Closed Won before the update cannot have its Amount changed.
     */
    public override void validateBeforeUpdate() {
        Opportunity opportunity = (Opportunity) getSObject();

        validateAmountNotNegative(opportunity);

        if ('Closed Won' == (String) opportunity.getUndirty('StageName')) {
            if (opportunity.Amount != (Decimal) opportunity.getUndirty('Amount')) {
                error('Amount cannot change on a won opportunity.', opportunity, 'Amount');
            }
        }
    }

    /**
     * Raises an error on the Amount field of the record if the Amount is negative.
     *
     * @param opportunity the opportunity to validate
     */
    private void validateAmountNotNegative(Opportunity opportunity) {
        if (opportunity.Amount != null && opportunity.Amount < 0) {
            error('Amount cannot be negative.', opportunity, 'Amount');
        }
    }
