import { LightningElement, api } from 'lwc';
import ADD_FAVORITE_LABEL from '@salesforce/label/c.Favorite_Add';
import REMOVE_FAVORITE_LABEL from '@salesforce/label/c.Favorite_Remove';

export default class FavoriteToggle extends LightningElement {
    /**
     * Whether the record is currently a favourite. Set by the parent;
     * the button re-renders whenever the parent changes it.
     *
     * @type {boolean}
     */
    @api favorite = false;

    get isFavorite() {
        return Boolean(this.favorite);
    }

    /**
     * Label of the action a click performs: Remove when already a
     * favourite, Add otherwise. Used for aria-label and title.
     *
     * @type {string}
     */
    get actionLabel() {
        return this.isFavorite ? REMOVE_FAVORITE_LABEL : ADD_FAVORITE_LABEL;
    }

    handleToggle() {
        const newFavorite = !this.isFavorite;
        // Optimistic update: flip the displayed state immediately,
        // before the parent/server confirms.
        this.favorite = newFavorite;
        this.dispatchEvent(
            new CustomEvent('favoritechange', {
                bubbles: true,
                composed: true,
                detail: { favorite: newFavorite }
            })
        );
    }
}
