        const domain = (this.email || '').toLowerCase().split('@')[1] || '';

        if (PERSONAL_DOMAINS.includes(domain)) {
            emailInput.setCustomValidity('Use your work email address.');
        } else {
            emailInput.setCustomValidity('');
        }

        // Step 2: report validity on every input so all invalid fields
        // surface their messages at once, even if an earlier one is invalid.
        const inputs = Array.from(this.template.querySelectorAll('[data-field]'));
        let isValid = true;
        inputs.forEach((input) => {
            if (!input.reportValidity()) {
                isValid = false;
            }
        });

        // Step 3: stop if any input is invalid.
        if (!isValid) {
            return;
        }

        // Step 4: call register imperatively and toast the outcome.
        register({ fullName: this.fullName, email: this.email, company: this.company })
            .then(() => {
                this.dispatchEvent(
                    new ShowToastEvent({
                        title: 'Registered',
                        message: 'Registration successful.',
                        variant: 'success'
                    })
                );
            })
            .catch((error) => {
                this.dispatchEvent(
                    new ShowToastEvent({
                        title: 'Registration failed',
                        message: error.body.message,
                        variant: 'error'
                    })
                );
            });
    }
