import { LightningElement, api } from 'lwc';

let instanceCount = 0;

export default class StatusListbox extends LightningElement {
  // Unique per-instance prefix so option ids never collide across instances.
  _uid;

  _value = '';
  _options = [];

  // Index of the "active" option (referenced by aria-activedescendant),
  // or -1 when there is no option.
  activeIndex = -1;

  @api label;

  constructor() {
    super();
    this._uid = ++instanceCount;
  }

  @api
  get options() {
    return this._options;
  }

  set options(newValue) {
    this._options = Array.isArray(newValue) ? newValue : [];
    this._reinitializeActiveOption();
  }

  @api
  get value() {
    return this._value;
  }

  set value(newValue) {
    this._value = newValue == null ? '' : newValue;
    if (this._options.length === 0) {
      return;
    }
    // When the parent changes the selected value, the active option moves to it.
    const index = this._options.findIndex((option) => option.value === this._value);
    if (index >= 0) {
      this.activeIndex = index;
    }
  }

  /**
   * Stable, per-instance id for the option at the given index.
   * Invoked from the template as optionId(index).
   */
  optionId(index) {
    return 'status-listbox-option-' + this._uid + '-' + index;
  }

  // Id of the active option; undefined when there is no active option,
  // which omits the aria-activedescendant attribute.
  get activeOptionId() {
    if (this.activeIndex < 0 || this.activeIndex >= this._options.length) {
      return undefined;
    }
    return this.optionId(this.activeIndex);
  }

  handleKeydown(event) {
    const key = event.key;
    // Only these six keys are handled; every other key (notably Tab)
    // keeps its default behaviour.
    if (!['ArrowDown', 'ArrowUp', 'Home', 'End', 'Enter', ' '].includes(key)) {
      return;
    }
    event.preventDefault();
    if (this._options.length === 0) {
      return;
    }
    switch (key) {
      case 'ArrowDown':
        // Move down one, stopping at the last option (no wrap-around).
        this._setActiveIndex(Math.min(this.activeIndex + 1, this._options.length - 1));
        break;
      case 'ArrowUp':
        // Move up one, stopping at the first option (no wrap-around).
        this._setActiveIndex(Math.max(this.activeIndex - 1, 0));
        break;
      case 'Home':
        this._setActiveIndex(0);
        break;
      case 'End':
        this._setActiveIndex(this._options.length - 1);
        break;
      case 'Enter':
      case ' ':
        // Select the active option. Moving never changes the selection;
        // Enter/space is what applies it.
        this._selectActiveOption();
        break;
    }
  }

  handleOptionClick(event) {
    const value =
      event.target && event.target.dataset ? event.target.dataset.value : undefined;
    const index = this._options.findIndex((option) => option.value === value);
    if (index < 0) {
      return;
    }
    // Clicking an option selects it and makes it the active option.
    this._setActiveIndex(index);
    this._selectValue(value);
  }

  // The active option starts as the selected option, or the first option
  // if nothing is selected.
  _reinitializeActiveOption() {
    if (this._options.length === 0) {
      this.activeIndex = -1;
      return;
    }
    const index = this._options.findIndex((option) => option.value === this._value);
    this.activeIndex = index >= 0 ? index : 0;
  }

  _setActiveIndex(index) {
    if (index !== this.activeIndex) {
      this.activeIndex = index;
    }
  }

  _selectActiveOption() {
    const option = this._options[this.activeIndex];
    if (option) {
      this._selectValue(option.value);
    }
  }

  // Selecting dispatches a `change` event with the new value, unless the
  // option was already selected (in which case nothing is dispatched).
  _selectValue(value) {
    if (value === this._value) {
      return;
    }
    this.value = value;
    this.dispatchEvent(new CustomEvent('change', { detail: { value } }));
  }
}
