/**
 * RecurringGiftService
 *
 * Records monthly-giving sign-ups coming from the nonprofit's donation form as
 * NPSP Enhanced Recurring Donations (npe03__Recurring_Donation__c).
 *
 * Design notes / bulk-safety:
 *  - Every request is validated BEFORE any DML, so a single bad record can
 *    never let a batch partially commit.
 *  - All Recurring Donation records are built up front and written with one
 *    bulk DML statement, so 200 requests in a single call use exactly one DML
 *    and zero SOQL queries of our own.
 *  - We only create the Recurring Donation record. NPSP's Enhanced Recurring
 *    Donations engine generates the installment Opportunities itself (each
 *    pointing back via Opportunity.npe03__Recurring_Donation__c), so we never
 *    insert Opportunities.
 *  - The returned Ids preserve the order of the input requests.
 */
public class RecurringGiftService {

    public class RecurringGiftException extends Exception {}

    public class GiftRequest {
        public Id contactId;
        public Decimal amount;
        public Integer dayOfMonth;    // 1-31
        public Date startDate;
        public Integer installments;  // null or 0 = no end date
        public String paymentMethod;  // 'Credit Card', 'ACH' or 'Check'
    }

    /**
     * Creates one Enhanced Recurring Donation per request and returns the new
     * record Ids in request order.
     */
    public static List<Id> createMonthlyGifts(List<GiftRequest> requests) {
        if (requests == null || requests.isEmpty()) {
            return new List<Id>();
        }

        // Validate the entire batch up front - no DML is reached unless every
        // request is valid.
        for (Integer i = 0; i < requests.size(); i++) {
            validateRequest(requests[i], i);
        }

        // Build the records in request order so the returned Ids match the input.
        List<npe03__Recurring_Donation__c> donations = new List<npe03__Recurring_Donation__c>();
        for (GiftRequest req : requests) {
            donations.add(buildRecurringDonation(req));
        }

        // One bulk DML statement for the whole batch. NPSP then generates the
        // installment Opportunities from these records.
        insert donations;

        // Collect the new Ids in request order (the list preserves insertion order).
        List<Id> ids = new List<Id>();
        for (npe03__Recurring_Donation__c rd : donations) {
            ids.add(rd.Id);
        }
        return ids;
    }

    /**
     * Validates a single request, throwing RecurringGiftException on the first
     * problem found. Runs before any DML.
     */
    private static void validateRequest(GiftRequest req, Integer index) {
        if (req == null) {
            throw new RecurringGiftException('GiftRequest at index ' + index + ' is null.');
        }
        if (req.contactId == null) {
            throw new RecurringGiftException('GiftRequest at index ' + index + ' is missing a donor contact.');
        }
        if (req.amount == null || req.amount <= 0) {
            throw new RecurringGiftException('GiftRequest at index ' + index + ' has a null or non-positive amount.');
        }
        if (req.dayOfMonth == null || req.dayOfMonth < 1 || req.dayOfMonth > 31) {
            throw new RecurringGiftException('GiftRequest at index ' + index + ' has dayOfMonth outside the 1-31 range.');
        }
        if (req.startDate == null) {
            throw new RecurringGiftException('GiftRequest at index ' + index + ' is missing a start date.');
        }
    }

    /**
     * Maps a valid GiftRequest to an Enhanced Recurring Donation record.
     */
    private static npe03__Recurring_Donation__c buildRecurringDonation(GiftRequest req) {
        // null or 0 installments = open-ended (no end date); otherwise fixed
        // length with that many planned installments.
        Boolean openEnded = (req.installments == null || req.installments == 0);

        npe03__Recurring_Donation__c rd = new npe03__Recurring_Donation__c();
        rd.npe03__Contact__c               = req.contactId;
        rd.npe03__Amount__c                = req.amount;
        rd.npe03__Installment_Period__c    = 'Monthly';
        rd.npsp__InstallmentFrequency__c   = 'Monthly';
        rd.npsp__RecurringType__c          = 'Recurring';
        rd.npsp__PaymentMethod__c          = req.paymentMethod;
        rd.npsp__Status__c                = 'Active';
        rd.npsp__StartDate__c              = req.startDate;
        rd.npe03__Next_Payment_Date__c     = req.startDate;
        rd.npe03__Date_Established__c      = req.startDate;

        // The form's "31" means "last day of the month" - store it with ERP's own
        // last-day-of-month option. 29 and 30 are stored as plain days of month.
        if (req.dayOfMonth == 31) {
            rd.npsp__Day_of_Month__c                 = 31;
            rd.npsp__Always_Use_Last_Day_Of_Month__c = true;
        } else {
            rd.npsp__Day_of_Month__c                 = req.dayOfMonth;
            rd.npsp__Always_Use_Last_Day_Of_Month__c = false;
        }

        if (openEnded) {
            rd.npe03__Schedule_Type__c     = 'Open Ended';
            rd.npe03__Open_Ended_Status__c = true;
        } else {
            rd.npe03__Schedule_Type__c = 'Fixed Length';
            rd.npe03__Installments__c  = req.installments;
        }

        return rd;
    }
}
