/**
 * FamilyService
 *
 * Records parent/child relationships in NPSP for a bulk import.
 *
 * For every (child, parent) pair this method inserts the *forward* relationship:
 *
 *     npe4__Contact__c        = child
 *     npe4__RelatedContact__c = parent
 *     npe4__Type__c          = 'Parent'
 *     npe4__Status__c        = 'Current'
 *
 * Because NPSP Relationships in this org use the default "List Setting" reciprocal
 * method, the NPSP relationship trigger automatically creates the *reciprocal*
 * relationship for each record we insert:
 *
 *     npe4__Contact__c        = parent
 *     npe4__RelatedContact__c = child
 *     npe4__Type__c          = 'Son' / 'Daughter' / 'Child'
 *     npe4__Status__c        = 'Current'
 *
 * The reciprocal type is chosen by NPSP from the `Parent` Relationship Lookup
 * (Male -> Son, Female -> Daughter, Neutral -> Child) based on the child's gender,
 * and the two records are linked via npe4__ReciprocalRelationship__c.
 *
 * End state per pair: exactly one relationship in each direction.
 *
 * Re-runs are safe: any pair that already has a relationship in either direction is
 * skipped. The whole batch is bulk-safe and uses at most 1 SOQL query and 1 DML
 * statement of its own for any number of pairs.
 */
public class FamilyService {

    private static final String TYPE_PARENT  = 'Parent';
    private static final String STATUS_CURRENT = 'Current';

    public static void linkParents(Map<Id, Id> parentIdByChildId) {
        if (parentIdByChildId == null || parentIdByChildId.isEmpty()) {
            return;
        }

        // Collect every Contact that takes part in any pair so a single SOQL query
        // can load all the relationships we need to inspect for duplicates.
        Set<Id> involvedContacts = new Set<Id>();
        for (Map.Entry<Id, Id> entry : parentIdByChildId.entrySet()) {
            if (entry.getKey() != null && entry.getValue() != null) {
                involvedContacts.add(entry.getKey());
                involvedContacts.add(entry.getValue());
            }
        }
        if (involvedContacts.isEmpty()) {
            return;
        }

        // ONE SOQL query: every existing relationship touching any involved Contact.
        // We store an unordered pair key for both directions of each relationship so
        // that a pair with a relationship in EITHER direction is treated as a duplicate.
        Set<String> existingPairs = new Set<String>();
        for (npe4__Relationship__c rel : [
                SELECT npe4__Contact__c, npe4__RelatedContact__c
                FROM npe4__Relationship__c
                WHERE npe4__Contact__c IN :involvedContacts
                   OR npe4__RelatedContact__c IN :involvedContacts
            ]) {
            if (rel.npe4__Contact__c != null && rel.npe4__RelatedContact__c != null) {
                existingPairs.add(pairKey(rel.npe4__Contact__c, rel.npe4__RelatedContact__c));
                existingPairs.add(pairKey(rel.npe4__RelatedContact__c, rel.npe4__Contact__c));
            }
        }

        // Build the forward "Parent" relationships for pairs that don't already exist.
        List<npe4__Relationship__c> toInsert = new List<npe4__Relationship__c>();
        for (Map.Entry<Id, Id> entry : parentIdByChildId.entrySet()) {
            Id childId = entry.getKey();
            Id parentId = entry.getValue();
            if (childId == null || parentId == null) {
                continue;
            }
            // Skip if any relationship already exists between the two contacts.
            if (existingPairs.contains(pairKey(childId, parentId))) {
                continue;
            }

            npe4__Relationship__c rel = new npe4__Relationship__c();
            rel.npe4__Contact__c        = childId;   // child is the primary contact
            rel.npe4__RelatedContact__c = parentId;  // parent is the related contact
            rel.npe4__Type__c           = TYPE_PARENT;
            rel.npe4__Status__c         = STATUS_CURRENT;
            toInsert.add(rel);
        }

        // ONE DML statement for all new forward relationships. NPSP's trigger creates
        // and links the reciprocal relationship for each of them.
        if (!toInsert.isEmpty()) {
            insert toInsert;
        }
    }

    /**
     * Order-sensitive pair key. Both orderings of an existing relationship are stored,
     * so a single containment check is enough to detect a relationship in either direction.
     */
    private static String pairKey(Id a, Id b) {
        return String.valueOf(a) + '-' + String.valueOf(b);
    }
}
